INSERT INTO public.product_catalogue (product_id, product_name, slug, brand, product_group_id, product_type_id, goal_tags, aim_tags, search_tags, short_description, full_description, usage_information, ingredients, warnings_allergens, image_urls, serving_size_label, serving_size_g, calories, protein_g, carbohydrates_g, fat_g, fibre_g, sugar_g, sodium_mg, product_status, sort_order)
VALUES (
  'PROD-239',
  'Yoga Bar Muesli High Protein Breakfast',
  'yoga-bar-muesli-high-protein-breakfast',
  'Yoga Bar',
  (SELECT id FROM public.product_groups WHERE name = 'Health Foods' LIMIT 1),
  (SELECT id FROM public.product_types WHERE name = 'Breakfast & Grains' LIMIT 1),
  ARRAY['general-fitness'],
  ARRAY['Breakfast','Fibre','Protein Snack','Clean Eating'],
  ARRAY['yoga bar','muesli','high protein breakfast','quinoa','amaranth','no sugar','india'],
  '20g protein and 8g fibre per serving. No maida, no preservatives. India''s guilt-free muesli.',
  'Yoga Bar High Protein Muesli is packed with protein-rich ingredients like quinoa puffs, amaranth, roasted seeds, and dried fruits. Each serving delivers 20g of protein and 8g of dietary fibre with no refined flour, no preservatives, and no refined sugar. Perfect for a quick, healthy, filling breakfast.',
  'Eat with cold milk, plant milk, or yogurt. Can also be consumed dry as a snack.',
