INSERT INTO public.product_catalogue (product_id, product_name, slug, brand, product_group_id, product_type_id, goal_tags, aim_tags, search_tags, short_description, full_description, usage_information, ingredients, warnings_allergens, image_urls, serving_size_label, serving_size_g, calories, protein_g, carbohydrates_g, fat_g, fibre_g, sugar_g, sodium_mg, product_status, sort_order)
VALUES (
  'PROD-247',
  'Happilo Premium Roasted Mixed Nuts',
  'happilo-premium-roasted-mixed-nuts',
  'Happilo',
  (SELECT id FROM public.product_groups WHERE name = 'Health Foods' LIMIT 1),
  (SELECT id FROM public.product_types WHERE name = 'Nuts, Seeds & Nut Butters' LIMIT 1),
  ARRAY['general-fitness'],
  ARRAY['Healthy Fats','Heart Health','Protein Snack','Antioxidants'],
  ARRAY['mixed nuts','happilo','roasted nuts','cashew','almond','walnut','no salt'],
  'Dry roasted cashews, almonds, walnuts, and pistachios with no added oil or salt.',
  'Happilo Premium Mixed Nuts is a thoughtfully curated blend of dry-roasted cashews, almonds, walnuts, and pistachios — roasted without added oil, salt, or sugar. Rich in Omega-3 fatty acids, protein, magnesium, and antioxidants. A perfect everyday health snack for adults of all ages.',
