INSERT INTO public.product_catalogue (product_id, product_name, slug, brand, product_group_id, product_type_id, goal_tags, aim_tags, search_tags, short_description, full_description, usage_information, ingredients, warnings_allergens, image_urls, serving_size_label, serving_size_g, calories, protein_g, carbohydrates_g, fat_g, fibre_g, sugar_g, sodium_mg, product_status, sort_order)
VALUES (
  'PROD-292',
  'Wellbeing Nutrition Melts Multivitamin',
  'wellbeing-nutrition-melts-multivitamin',
  'Wellbeing Nutrition',
  (SELECT id FROM public.product_groups WHERE name = 'Vitamins' LIMIT 1),
  (SELECT id FROM public.product_types WHERE name = 'Vitamins & Minerals' LIMIT 1),
  ARRAY['general-fitness'],
  ARRAY['General Health','Immunity','Energy','Absorption'],
  ARRAY['wellbeing nutrition','melts','nano strip','multivitamin','india','vegan'],
  'Nano strip multivitamin that melts on your tongue. 34 essential vitamins and minerals.',
  'Wellbeing Nutrition Melts is India''s first nano strip multivitamin technology that dissolves on your tongue for fast, direct absorption — bypassing the digestive system. Packed with 34 vitamins and minerals, it supports energy, immunity, bone health, and cognitive performance. Vegan and sugar-free.',
