INSERT INTO public.product_catalogue (product_id, product_name, slug, brand, product_group_id, product_type_id, goal_tags, aim_tags, search_tags, short_description, full_description, usage_information, ingredients, warnings_allergens, image_urls, serving_size_label, serving_size_g, calories, protein_g, carbohydrates_g, fat_g, fibre_g, sugar_g, sodium_mg, product_status, sort_order)
VALUES (
  'PROD-320',
  'Glucosamine Chondroitin MSM Complex',
  'glucosamine-chondroitin-msm-complex',
  'Himalayan Organics',
  (SELECT id FROM public.product_groups WHERE name = 'Joint & Recovery' LIMIT 1),
  (SELECT id FROM public.product_types WHERE name = 'Joint & Recovery' LIMIT 1),
  ARRAY['general-fitness'],
  ARRAY['Joint Health','Anti-inflammatory','Recovery','Cartilage'],
  ARRAY['glucosamine','chondroitin','msm','joint health','cartilage','himalayan organics'],
  '1500mg glucosamine, 800mg chondroitin, 400mg MSM per serving for joint health.',
  'Himalayan Organics Glucosamine Chondroitin MSM delivers a clinically studied triple combination for comprehensive joint health. Glucosamine rebuilds cartilage, Chondroitin retains water in joints for shock absorption, and MSM reduces inflammation. Ideal for athletes, seniors, and anyone with joint discomfort.',
  'Take 3 tablets daily with food. Use consistently for 6–8 weeks for noticeable results.',
